style.css:
@-moz-document domain("discord.com") {
/* Background color for the main chat area */
  .appMount-3lHmkl {
    background-color: #d0eaff !important; /* soft sky blue */
  }

  /* Background for channels and sidebar */
  .sidebar-1tnWFu,
  .container-2cd8Mz {
    background-color: #b3ddf2 !important;
  }

  /* Chat messages background */
  .messageListItem-ZZ7v6g {
    background-color: #e6f5ff !important;
  }

  /* Top bar (server name area) */
  .title-31SJ6t {
    background-color: #a1cbe8 !important;
    color: #003b6f !important; /* darker text */
  }

  /* Message text */
  .markup-eYLPri {
    color: #003b6f !important;
  }

  /* Username colors */
  .username-h_Y3Us {
    color: #045b99 !important;
  }

  /* Scrollbars */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-track {
    background: #b3ddf2;
  }
  ::-webkit-scrollbar-thumb {
    background: #6eb3d6;
    border-radius: 10px;
  }

  /* Buttons (like send) */
  .button-2fCJ0o {
    background-color: #aee0ff !important;
    color: #003b6f !important;
  }

  /* Chatbox */
  .channelTextArea-1FufC0 {
    background-color: #d0eaff !important;
  }
}
